"""ORD_LINE renumbering for migrated Meridian CRM data."""

from decimal import Decimal, InvalidOperation


def _line_number(value: object) -> Decimal:
    """Return a numeric sort key, treating blank or missing values as zero."""
    if value == "":
        return Decimal(0)
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted rows and assign contiguous line numbers per order."""
    surviving: list[tuple[str, Decimal, int, dict]] = []

    for original_index, row in enumerate(lines):
        if row.get("DEL_FLG", "") == "Y":
            continue

        order_id = str(row.get("ORD_ID", ""))
        line_no = _line_number(row.get("LINE_NO", ""))
        surviving.append((order_id, line_no, original_index, row))

    surviving.sort(key=lambda item: (item[0], item[1], item[2]))

    result: list[dict] = []
    current_order_id: str | None = None
    next_line_no = 0

    for order_id, _, _, row in surviving:
        if order_id != current_order_id:
            current_order_id = order_id
            next_line_no = 1
        else:
            next_line_no += 1

        new_row = dict(row)
        new_row["LINE_NO"] = next_line_no
        result.append(new_row)

    return result
